const WALK_SPEED = 3.2;
const RUN_SPEED = 5.6;
const SPRINT_SPEED = 8.4;
const TURN_RATE = 3.4;
const RADIUS = 0.45;
const GRAVITY = 22;
const JUMP_VEL = 7.2;

function limbGeometry(w, h, d) {
