    ctx.beginPath();
    ctx.arc(0, 0, r - 4, redStart, a1);
    ctx.strokeStyle = 'rgba(255,60,50,0.75)';
    ctx.stroke();

    const frac = clamp(shownSpeed / MAX_KMH, 0, 1);
    ctx.beginPath();
    ctx.arc(0, 0, r - 4, a0, a0 + (a1 - a0) * frac);
