      ctx.strokeStyle = v >= 175 ? 'rgba(255,90,70,0.9)' : 'rgba(200,205,215,0.6)';
      ctx.lineWidth = v % 40 === 0 ? 2 : 1;
      ctx.stroke();
      if (v % 40 === 0) ctx.fillText(String(v), Math.cos(a) * (r - 26), Math.sin(a) * (r - 26) + 3);
