      text += `  —  ${d} m`;
    }
    const status = active.state === 'failed'
      ? 'FAILED'
      : active.stepIndex === active.def.steps.length - 1
        ? 'FINAL OBJECTIVE'
        : `OBJECTIVE ${active.stepIndex + 1}/${active.def.steps.length}`;
    hud.setMission(active.def.title, text, status);
