    if (step?.type === 'reach-safe' && deps.police?.isSpotted?.()) {
      active.spottedTimer += 1 / 60;
      if (active.spottedTimer >= MISSION_TUNING.spottedFailSeconds) { fail('IDENTIFIED'); return true; }
